import React, { useState, useEffect } from 'react';

const navItems = [
  { label: 'Home',           href: '#home' },
  { label: 'Education',      href: '#education' },
  { label: 'Skills',         href: '#skills' },
  { label: 'Projects',       href: '#projects' },
  { label: 'Experience',     href: '#experience' },
  { label: 'Certifications', href: '#certifications' },
  { label: 'Contact',        href: '#contact' },
];

const Header = () => {
  const [scrolled, setScrolled]   = useState(false);
  const [menuOpen, setMenuOpen]   = useState(false);
  const [active, setActive]       = useState('#home');

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const handleNav = (e, href) => {
    e.preventDefault(); setActive(href); setMenuOpen(false);
    const el = document.querySelector(href);
    if (el) el.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <header style={{
      position: 'fixed', top: 0, left: 0, right: 0, zIndex: 1000,
      padding: '0 2rem', height: 70,
      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      background: scrolled ? 'rgba(26,15,24,0.92)' : 'transparent',
      backdropFilter: scrolled ? 'blur(20px)' : 'none',
      borderBottom: scrolled ? '1px solid rgba(232,121,154,0.12)' : 'none',
      transition: 'all 0.3s ease',
    }}>
      {/* Logo */}
      <a href="#home" onClick={e => handleNav(e,'#home')} style={{ textDecoration:'none' }}>
        <div style={{ display:'flex', alignItems:'center', gap:'0.75rem' }}>
          <div style={{
            width: 38, height: 38, borderRadius: '50%',
            background: 'linear-gradient(135deg, #e8799a, #b882d4)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontFamily: "'Cormorant Garamond', serif",
            fontWeight: 700, fontSize: '0.95rem', color: '#fff',
            boxShadow: '0 0 20px rgba(232,121,154,0.45)',
          }}>MG</div>
          <span style={{
            fontFamily: "'Cormorant Garamond', serif",
            fontWeight: 600, fontSize: '1.05rem', color: '#fdf0f4',
          }} className="logo-name">Maithily Gondode</span>
        </div>
      </a>

      {/* Desktop nav */}
      <nav style={{ display:'flex', gap:'0.25rem' }} className="desktop-nav-items">
        {navItems.map(item => (
          <a key={item.href} href={item.href}
            onClick={e => handleNav(e, item.href)}
            style={{
              padding: '0.4rem 0.85rem', borderRadius: '50px',
              fontFamily: "'Nunito', sans-serif", fontSize: '0.88rem',
              fontWeight: active === item.href ? 700 : 400,
              color: active === item.href ? '#e8799a' : 'rgba(253,240,244,0.7)',
              background: active === item.href ? 'rgba(232,121,154,0.1)' : 'transparent',
              border: active === item.href ? '1px solid rgba(232,121,154,0.35)' : '1px solid transparent',
              transition: 'all 0.2s ease', textDecoration: 'none',
            }}
            onMouseEnter={e => { if (active !== item.href) { e.target.style.color='#fdf0f4'; e.target.style.background='rgba(255,255,255,0.05)'; }}}
            onMouseLeave={e => { if (active !== item.href) { e.target.style.color='rgba(253,240,244,0.7)'; e.target.style.background='transparent'; }}}
          >{item.label}</a>
        ))}
      </nav>

      {/* Mobile hamburger */}
      <button onClick={() => setMenuOpen(!menuOpen)}
        style={{ display:'none', background:'none', border:'none', cursor:'pointer', color:'#fdf0f4', fontSize:'1.4rem', padding:'0.5rem' }}
        className="mobile-menu-btn" aria-label="Menu">
        {menuOpen ? '✕' : '☰'}
      </button>

      {menuOpen && (
        <div style={{
          position:'absolute', top:70, left:0, right:0,
          background:'rgba(26,15,24,0.97)', backdropFilter:'blur(20px)',
          borderBottom:'1px solid rgba(232,121,154,0.15)', padding:'1rem 0',
        }}>
          {navItems.map(item => (
            <a key={item.href} href={item.href}
              onClick={e => handleNav(e, item.href)}
              style={{
                display:'block', padding:'0.75rem 2rem',
                fontFamily:"'Nunito', sans-serif",
                color: active === item.href ? '#e8799a' : 'rgba(253,240,244,0.8)',
                fontSize:'0.95rem', fontWeight: active === item.href ? 700 : 400,
                textDecoration:'none',
                borderLeft: active === item.href ? '3px solid #e8799a' : '3px solid transparent',
              }}
            >{item.label}</a>
          ))}
        </div>
      )}

      <style>{`
        @media (max-width:768px) {
          .desktop-nav-items { display:none !important; }
          .mobile-menu-btn   { display:block !important; }
          .logo-name         { display:none !important; }
        }
        @media (min-width:769px) { .logo-name { display:block !important; } }
      `}</style>
    </header>
  );
};

export default Header;
